// Custom SVG-based chamfered cards for tech-forward industrial UI
const ChamferedPanel: React.FC<{
  width: number;
  height: number;
  borderWidth?: number;
  borderColor?: string;
  backgroundColor?: string;
  children?: React.ReactNode;
  style?: React.CSSProperties;
}> = ({
  width,
  height,
  borderWidth = 1.5,
  borderColor = "#a40404",
  backgroundColor = "rgba(10, 10, 10, 0.75)",
  children,
  style,
}) => {
  const chamfer = 16; // corner cut depth
  const points = `
    ${chamfer},0 
    ${width - chamfer},0 
    ${width},${chamfer} 
    ${width},${height - chamfer} 
    ${width - chamfer},${height} 
    ${chamfer},${height} 
    0,${height - chamfer} 
    0,${chamfer}
  `.replace(/\s+/g, " ").trim();

  return (
    <div style={{ width, height, position: "relative", ...style }}>
      <svg
        width={width}
        height={height}
        style={{ position: "absolute", top: 0, left: 0 }}
      >
        <polygon
          points={points}
          fill={backgroundColor}
          stroke={borderColor}
          strokeWidth={borderWidth}
        />
      </svg>
      <div
        style={{
          position: "absolute",
          top: borderWidth,
          left: borderWidth,
          width: width - borderWidth * 2,
          height: height - borderWidth * 2,
          padding: "24px 16px",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          boxSizing: "border-box",
        }}
      >
        {children}
      </div>
    </div>
  );
};

