const PreventativeMaintenance: React.FC<PreventativeMaintenanceProps> = ({
  backgroundColor = "#090808",
  transparentBackground = false,
  durationInSeconds = 10,
  label = "MAINTENANCE",
  titlePart1 = "Preventative Maintenance –",
  titlePart2 = "Proactive by Design",
  rightBodyText = "The 15SCH doesn't wait for failures. Built-in maintenance intelligence tracks runtime, monitors filter conditions, and alerts operators before small issues become costly repairs.",
  highlightLabel = "Condenser Cleaning Mode",
  highlightSubtext = "optimizes heat exchange efficiency automatically.",
  accentColor = "#a40404",
  cards,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safely parse/resolve cards in case it is passed as a serialized JSON string or is undefined
  const resolvedCards = React.useMemo(() => {
    if (!cards) return defaultCards;
    if (typeof cards === "string") {
      try {
        const parsed = JSON.parse(cards);
        if (Array.isArray(parsed)) return parsed;
      } catch (e) {
        // Fallback to default
      }
      return defaultCards;
    }
    if (Array.isArray(cards)) return cards;
    return defaultCards;
  }, [cards]);

  // Helper function to render correct dynamic icons
  const renderIcon = (type: string, size: number, rot: number) => {
    switch (type) {
      case "speedometer":
        return <SpeedometerIcon size={size} color={accentColor} />;
      case "filter":
        return <FilterIcon size={size} color={accentColor} />;
      case "calendar":
        return <CalendarIcon size={size} color={accentColor} />;
      case "fan":
        return <FanIcon size={size} color={accentColor} rotation={rot} />;
      case "shield":
        return <ShieldIcon size={size} color={accentColor} />;
      default:
        return <SpeedometerIcon size={size} color={accentColor} />;
    }
  };

  // Pure mathematical derivations for the entrance timings
  const labelAlpha = interpolate(frame, [10, 30], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const labelX = interpolate(frame, [10, 30], [-25, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const lineScaleX = interpolate(frame, [15, 45], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const headlineSpring = spring({ frame, fps, config: { damping: 16, stiffness: 70, mass: 0.9 }, delay: 20 });
  const rightBodySpring = spring({ frame, fps, config: { damping: 18, stiffness: 60, mass: 1 }, delay: 65 });
  const highlightSpring = spring({ frame, fps, config: { damping: 16, stiffness: 50, mass: 1.1 }, delay: 85 });

  // Soft pulsing glow size on top-left to enrich the background atmospherics
  const glowOpacity = interpolate(frame, [0, 300], [0.85, 1.15], { extrapolateRight: "clamp" });
  const radialGlow = `radial-gradient(circle at 10% 10%, ${accentColor}3c 0%, transparent 55%)`;

  // Dynamic continuous spinning rotation for all fans to look premium
  const fanRotation = (frame * 2.8) % 360;

  // Background and safe zone logic
  const actualBgColor = transparentBackground ? "transparent" : backgroundColor;

  return (
    <AbsoluteFill style={{ backgroundColor: actualBgColor, fontFamily: interFamily }}>
      {/* Background Cinematic Flare Layer */}
      {!transparentBackground && (
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            backgroundImage: radialGlow,
            opacity: glowOpacity,
            pointerEvents: "none",
          }}
        />
      )}

      {/* HEADER SECTION (Top-left safe zone) */}
      <div
        style={{
          position: "absolute",
          top: height * 0.08,
          left: width * 0.05,
          width: width * 0.9,
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-start",
        }}
      >
        {/* Uppercase Category Label */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "flex-start",
            opacity: labelAlpha,
            transform: `translateX(${labelX}px)`,
            transition: "none",
          }}
        >
          <div
            style={{
              fontSize: 15,
              fontWeight: 900,
              letterSpacing: 4.5,
              color: accentColor,
              fontFamily: archivoFamily,
              textTransform: "uppercase",
              marginBottom: 6,
            }}
          >
            {label}
          </div>
          <div
            style={{
              width: 140,
              height: 2.5,
              backgroundColor: accentColor,
              transformOrigin: "left",
              transform: `scaleX(${lineScaleX})`,
              boxShadow: `0 0 10px ${accentColor}`,
              transition: "none",
            }}
          />
        </div>

        {/* Cinematic Headline */}
        <h1
          style={{
            fontSize: 55,
            fontWeight: 900,
            lineHeight: 1.15,
            margin: "18px 0 0 0",
            fontFamily: archivoFamily,
            opacity: headlineSpring,
            transform: `translateY(${(1 - headlineSpring) * 20}px)`,
            transition: "none",
            letterSpacing: "-0.5px",
          }}
        >
          <span style={{ color: "#ffffff" }}>{titlePart1} </span>
          <span style={{ color: accentColor }}>{titlePart2}</span>
        </h1>
      </div>

      {/* FIVE SEQUENTIAL SLIDING CARDS SECTION (Horizontal row) */}
      <div
        style={{
          position: "absolute",
          top: height * 0.38,
          left: width * 0.05,
          width: width * 0.54,
          height: height * 0.53,
          display: "flex",
          flexDirection: "row",
          justifyContent: "space-between",
          alignItems: "center",
          boxSizing: "border-box",
        }}
      >
        {resolvedCards.map((card: any, idx: number) => {
          // Precise spring calculation with cumulative delay for sequential entrance
          const cardSpring = spring({
            frame,
            fps,
            config: { damping: 15, stiffness: 60, mass: 0.85 },
            delay: 35 + idx * 8,
          });

          const cardWidth = width * 0.1;
          const cardHeight = height * 0.51;

          return (
            <ChamferedPanel
              key={idx}
              width={cardWidth}
              height={cardHeight}
              borderColor={`${accentColor}7a`}
              backgroundColor="rgba(9, 8, 8, 0.85)"
              style={{
                opacity: cardSpring,
                transform: `translateY(${(1 - cardSpring) * 80}px)`,
                transition: "none",
              }}
            >
              {/* Dynamic premium vector icon */}
              <div style={{ marginTop: height * 0.015, height: height * 0.08, display: "flex", alignItems: "center" }}>
                {renderIcon(card.iconType || "speedometer", width * 0.038, fanRotation)}
              </div>

              {/* Card Title */}
              <div
                style={{
                  fontFamily: archivoFamily,
                  fontSize: 19,
                  fontWeight: 800,
                  color: "#ffffff",
                  textAlign: "left",
                  width: "100%",
                  lineHeight: 1.25,
                  marginTop: height * 0.03,
                  minHeight: height * 0.09,
                }}
              >
                {card.title || ""}
              </div>

              {/* Delicate Separator */}
              <div
                style={{
                  width: "100%",
                  height: 1,
                  backgroundColor: "rgba(255, 255, 255, 0.12)",
                  margin: `${height * 0.015}px 0`,
                }}
              />

              {/* Card Description Subtext */}
              <div
                style={{
                  fontFamily: interFamily,
                  fontSize: 13,
                  fontWeight: 400,
                  color: "#a3a3a3",
                  textAlign: "left",
                  width: "100%",
                  lineHeight: 1.45,
                }}
              >
                {card.description || ""}
              </div>
            </ChamferedPanel>
          );
        })}
      </div>

      {/* RIGHT SIDE DETAILS SECTION */}
      <div
        style={{
          position: "absolute",
          top: height * 0.38,
          right: width * 0.05,
          width: width * 0.32,
          display: "flex",
          flexDirection: "column",
          justifyContent: "flex-start",
        }}
      >
        {/* Body Text Block */}
        <div
          style={{
            fontFamily: interFamily,
            fontSize: 24,
            fontWeight: 400,
            lineHeight: 1.5,
            color: "#e5e5e5",
            marginBottom: height * 0.045,
            opacity: rightBodySpring,
            transform: `translateY(${(1 - rightBodySpring) * 20}px)`,
            transition: "none",
          }}
        >
          {rightBodyText}
        </div>

        {/* Action Callout / Highlight Box */}
        <ChamferedPanel
          width={width * 0.32}
          height={height * 0.19}
          borderColor={accentColor}
          backgroundColor="rgba(164, 4, 4, 0.07)"
          style={{
            opacity: highlightSpring,
            transform: `translateY(${(1 - highlightSpring) * 30}px)`,
            transition: "none",
          }}
        >
          <div
            style={{
              display: "flex",
              flexDirection: "row",
              alignItems: "center",
              width: "100%",
              height: "100%",
            }}
          >
            {/* Spinning fan icon in highlight box */}
            <div style={{ marginRight: 22 }}>
              <FanIcon size={width * 0.048} color={accentColor} rotation={fanRotation} />
            </div>

            {/* Structured description text */}
            <div
              style={{
                flex: 1,
                display: "flex",
                flexDirection: "column",
                justifyContent: "center",
              }}
            >
              <div
                style={{
                  fontFamily: archivoFamily,
                  fontSize: 21,
                  fontWeight: 800,
                  color: accentColor,
                  marginBottom: 4,
                  lineHeight: 1.2,
                }}
              >
                {highlightLabel}
              </div>
              <div
                style={{
                  fontFamily: interFamily,
                  fontSize: 19,
                  fontWeight: 400,
                  color: "#ffffff",
                  lineHeight: 1.35,
                }}
              >
                {highlightSubtext}
              </div>
            </div>
          </div>
        </ChamferedPanel>
      </div>
    </AbsoluteFill>
  );
};

